G=load()

def transform(grid):
    H=len(grid); W=len(grid[0])
    rows=[r for r in range(H) if any(grid[r])]
    if not rows: return [row[:] for row in grid]
    r0,r1=min(rows),max(rows)
    out=[[0]*W for _ in range(H)]
    for r in range(r0,r1+1):
        shift=r1-r
        for c in range(W):
            if grid[r][c]:
                nc=c-shift
                if 0<=nc<W: out[r][nc]=grid[r][c]
    return out

